"""Build the claim-level human review inbox."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
claims=json.loads((ROOT/"data/human_review_selection.json").read_text(encoding="utf-8"))["claims"]
payload=json.dumps(claims,ensure_ascii=False).replace("</","<\\/")
html="""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Human review · Composio Report</title><style>
:root{--ink:#1d1d1f;--muted:#6e6e73;--line:#d2d2d7;--paper:#f5f5f7;--blue:#06c;--green:#26734d}*{box-sizing:border-box}body{margin:0;background:white;color:var(--ink);font:16px/1.5 -apple-system,BlinkMacSystemFont,"Helvetica Neue",Arial,sans-serif}.wrap{max-width:1160px;margin:auto;padding:28px}.back,a{color:var(--blue);text-decoration:none}.hero{padding:28px 0 18px}.eyebrow,.rank{font-size:12px;color:var(--muted);letter-spacing:.08em;text-transform:uppercase}h1{font-size:clamp(34px,5vw,48px);letter-spacing:-.045em;margin:8px 0}.lead{font-size:18px;color:#48484a;max-width:780px}.notice{margin:16px 0;padding:13px 16px;background:var(--paper);border-radius:12px;color:#515156;font-size:14px}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin:20px 0}.metric{border-top:1px solid var(--line);padding:9px 3px}.metric strong{display:block;font-size:24px}.metric span{font-size:12px;color:var(--muted)}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.toolbar input,.toolbar select,.form input,.form select,.form textarea{font:inherit;padding:9px 11px;border:1px solid #d4d4db;border-radius:9px;background:white}.toolbar input{flex:1;min-width:220px}.button{border:0;background:#1d1d1f;color:white;font-weight:600;padding:10px 15px;border-radius:20px;cursor:pointer}.button.secondary{background:#efeff2;color:var(--ink)}.status{font-size:13px;color:var(--muted);min-height:22px}.card{border-top:1px solid var(--line);padding:20px 0 22px;scroll-margin-top:10px}.head{display:flex;justify-content:space-between;gap:15px}.head h2{font-size:21px;margin:2px 0}.meta,.muted{font-size:13px;color:var(--muted)}.score{font-size:12px;color:#666;background:#f1f1f4;padding:5px 9px;border-radius:18px;height:max-content}.why{font-size:14px;color:#444;margin:11px 0;padding-left:12px;border-left:2px solid #d7d7dd}.compare{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:13px 0}.finding{border:1px solid #e5e5ea;border-radius:10px;padding:11px}.finding h3{font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);margin:0 0 5px}.finding p{font-size:14px;margin:0;white-space:pre-wrap}.docs{display:flex;flex-wrap:wrap;gap:8px 14px;font-size:13px;margin:10px 0}.quote{font-size:13px;color:var(--muted);margin:6px 0}.form{display:grid;grid-template-columns:170px minmax(180px,1fr) minmax(220px,1.5fr) 150px;gap:9px;align-items:start;padding:12px;background:#f7f7f9;border-radius:11px;margin-top:12px}.form label{display:block;font-size:11px;text-transform:uppercase;color:var(--muted);margin-bottom:4px}.form input,.form select,.form textarea{width:100%;font-size:13px}.form textarea{min-height:43px}.saved{font-size:12px;color:var(--green);margin-top:4px}.empty{color:var(--muted)}@media(max-width:780px){.metrics{grid-template-columns:repeat(3,1fr)}.compare{grid-template-columns:1fr}.form{grid-template-columns:1fr 1fr}}@media(max-width:520px){.wrap{padding:18px}.metrics{grid-template-columns:repeat(2,1fr)}.head{display:block}.form{grid-template-columns:1fr}}
</style></head><body><main class="wrap"><a class="back" href="index.html">‹ Back to the report</a><header class="hero"><div class="eyebrow">Human review</div><h1>Check the findings that need a closer look.</h1><p class="lead">Review 20 flagged findings against the linked official pages. Choose an outcome and save. No API key is needed.</p><div class="notice"><b>Why these findings?</b> They were selected because the agents disagreed, page evidence was missing, access or credentials were unclear, or the answer could change a build decision. Each card explains its reason.</div></header><section class="metrics" aria-live="polite"><div class="metric"><strong>20</strong><span>Findings selected</span></div><div class="metric"><strong id="mreviewed">0 / 20</strong><span>Reviewed</span></div><div class="metric"><strong id="mpercent">0%</strong><span>Complete</span></div><div class="metric"><strong id="mcorrect">0</strong><span>Confirmed</span></div><div class="metric"><strong id="mincorrect">0</strong><span>Corrected</span></div><div class="metric"><strong id="muncertain">0</strong><span>Could not confirm</span></div></section><div class="notice"><b>Human-audited accuracy</b> = confirmed ÷ (confirmed + corrected). “Could not confirm” is excluded and shown separately. <span id="accuracy">Not measured yet.</span> <span id="remaining"></span></div><div class="toolbar"><input id="search" placeholder="Find an app or finding"><select id="filter"><option value="">All findings</option><option value="unreviewed">Not reviewed</option><option value="correct">Confirmed</option><option value="incorrect">Corrected</option><option value="uncertain">Could not confirm</option></select><button class="button secondary" id="backup">Download review record</button></div><p class="status" id="connection" role="status">Connecting to your review record…</p><div id="inbox"></div></main><script>
const claims=__CLAIMS__;let audits=[],localMode=false;const localKey="composio-human-review-audit-v1";const esc=x=>String(x??"").replace(/[&<>\"']/g,c=>c==="&"?"&amp;":c==="<"?"&lt;":c===">"?"&gt;":c.charCodeAt(0)===34?"&quot;":"&#39;");const labels={api_access:"API access",credential_requirements:"Getting credentials",auth_methods:"Authentication",pricing_restrictions:"Pricing restrictions",buildability:"Buildability",blocker:"Main blocker",api_type:"API type",endpoints:"Endpoints",capabilities:"API coverage",scopes:"Permissions",read_write:"Read and write",rate_limits:"Rate limits",webhooks:"Webhooks",mcp_or_agent_support:"MCP support",description:"Description"};const key=c=>c.app_id+"|"+c.field,record=c=>audits.find(x=>key(x)===key(c));function mergeRecord(rec){let i=audits.findIndex(x=>key(x)===key(rec));if(i<0)audits.push(rec);else audits[i]=rec;localStorage.setItem(localKey,JSON.stringify(audits))}function metrics(){let done=claims.filter(c=>record(c)?.final_outcome).length,counts={correct:0,incorrect:0,uncertain:0};audits.forEach(a=>{if(counts[a.final_outcome]!==undefined)counts[a.final_outcome]++});let n=counts.correct+counts.incorrect;document.querySelector("#mreviewed").textContent=`${done} / 20`;document.querySelector("#mpercent").textContent=`${Math.round(done/20*100)}%`;document.querySelector("#mcorrect").textContent=counts.correct;document.querySelector("#mincorrect").textContent=counts.incorrect;document.querySelector("#muncertain").textContent=counts.uncertain;document.querySelector("#accuracy").textContent=n?`${Math.round(counts.correct/n*100)}% across ${n} resolved claims.`:"Not measured yet.";document.querySelector("#remaining").textContent=`${20-done} remaining.`}function render(){const q=document.querySelector("#search").value.toLowerCase(),f=document.querySelector("#filter").value;const visible=claims.filter(c=>{let s=record(c)?.final_outcome||"unreviewed";return(!f||f===s)&&(!q||`${c.app} ${c.category} ${c.field_label}`.toLowerCase().includes(q))});document.querySelector("#inbox").innerHTML=visible.map(c=>{let a=record(c)||{},docs=c.official_sources||[],quotes=[...(c.researcher_evidence||[]).map(e=>["Researcher",e.quote,e.source_url]),...(c.evaluator_evidence||[]).map(e=>["Evaluator",e.quote,e.source_url])];let evreason=c.evaluator_reason||c.evaluator_finding||"No separate explanation provided.";return `<article class="card"><header class="head"><div><span class="rank">CLAIM ${c.rank} OF 20</span><h2>${esc(c.app)}</h2><div class="meta">${esc(c.category)} · ${esc(c.field_label)}</div></div><span class="score">Review priority ${c.score}</span></header><p class="why"><b>Why flagged:</b> ${c.selection_reasons.map(esc).join(" · ")}</p><div class="compare"><div class="finding"><h3>First research pass</h3><p>${esc(c.first_pass_claim)}</p></div><div class="finding"><h3>Researcher finding</h3><p>${esc(c.researcher_claim)}</p></div><div class="finding"><h3>Independent check</h3><p><b>${esc(c.evaluator_outcome)}</b><br>${esc(evreason)}</p></div></div><div class="docs"><b>Official documentation:</b>${docs.map(d=>`<a href="${esc(d.url)}" target="_blank" rel="noopener">${esc(d.title||d.url)} ↗</a>`).join("")||"No official page captured. Search the app’s developer docs."}</div>${quotes.map(x=>`<p class="quote"><b>${esc(x[0])} excerpt:</b> “${esc(x[1])}” ${x[2]?`<a href="${esc(x[2])}" target="_blank">Source ↗</a>`:""}</p>`).join("")}<form class="form" data-key="${esc(key(c))}"><div><label>Your decision</label><select name="outcome" required><option value="">Choose an outcome…</option>${["correct","incorrect","uncertain"].map(v=>`<option value="${v}" ${a.final_outcome===v?"selected":""}>${v[0].toUpperCase()+v.slice(1)}</option>`).join("")}</select></div><div><label>Your correction · optional</label><input name="corrected" value="${esc(a.corrected_finding||"")}" placeholder="If the finding needs correction, enter it here"></div><div><label>Official page checked and note</label><textarea name="comment" required placeholder="Paste the official page URL, then add a short note">${esc(a.evidence_urls?.[0]||"")}${a.reviewer_comment?"\\n"+esc(a.reviewer_comment):""}</textarea></div><div><label>Reviewer initials</label><input name="reviewer" required value="${esc(a.reviewer||"")}" placeholder="Name or initials"><button class="button" type="submit">Save this review</button>${a.final_outcome?`<div class="saved">Saved ${esc((a.reviewed_at||"").slice(0,10))}</div>`:""}</div></form></article>`}).join("")||"<p class=empty>No claims match this filter.</p>";metrics()}async function load(){try{let r=await fetch("/api/audit");if(!r.ok)throw Error();audits=await r.json();document.querySelector("#connection").textContent="Connected. Saved reviews are recorded in data/audit.json on this computer."}catch{localMode=true;try{audits=JSON.parse(localStorage.getItem(localKey)||"[]")}catch{audits=[]}document.querySelector("#connection").textContent="Saved in this browser. Download the review record to add it to data/audit.json."}render()}document.querySelector("#inbox").addEventListener("submit",async e=>{let form=e.target.closest("form[data-key]");if(!form)return;e.preventDefault();let c=claims.find(x=>key(x)===form.dataset.key),fd=new FormData(form),text=String(fd.get("comment")||"").trim(),parts=text.split(/\\r?\\n/),url=parts.shift().trim(),reviewer=String(fd.get("reviewer")||"").trim();if(!url||!reviewer){alert("Add the official page URL and reviewer initials before saving.");return}let rec={app_id:c.app_id,app:c.app,category:c.category,field:c.field,field_label:c.field_label,first_pass_claim:c.first_pass_claim,researcher_claim:c.researcher_claim,evaluator_outcome:c.evaluator_outcome,evaluator_finding:c.evaluator_finding,selection_reasons:c.selection_reasons,first_pass_outcome:null,final_outcome:fd.get("outcome"),corrected_finding:String(fd.get("corrected")||"").trim(),evidence_urls:[url],reviewer,reviewer_comment:parts.join("\\n").trim(),reviewed_at:new Date().toISOString()};if(localMode){mergeRecord(rec);document.querySelector("#connection").textContent="Saved in this browser. Download the audit backup to include it in the report.";render();return}try{let r=await fetch("/api/audit",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(rec)}),b=await r.json();if(!r.ok)throw Error(b.error||"Save failed");audits=b.audits;localStorage.setItem(localKey,JSON.stringify(audits));document.querySelector("#connection").textContent="Saved to data/audit.json. The report metrics have been refreshed.";render()}catch{localMode=true;mergeRecord(rec);document.querySelector("#connection").textContent="Saved in this browser. Download the audit backup to include it in the report.";render()}});document.querySelector("#search").addEventListener("input",render);document.querySelector("#filter").addEventListener("change",render);document.querySelector("#backup").addEventListener("click",async()=>{let x=audits;if(!localMode){try{let r=await fetch("/api/audit");x=await r.json()}catch{x=audits}}let b=new Blob([JSON.stringify(x,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(b);a.download="audit.json";a.click();URL.revokeObjectURL(a.href)});load();
</script></body></html>"""
(ROOT/"human-review.html").write_text(html.replace("__CLAIMS__",payload),encoding="utf-8")
print(f"Built human-review.html with {len(claims)} claims.")
